48	[[nodiscard]] inline double lp_text_d(cx::XmlNode const* n, double def) noexcept {
49	    if (n == nullptr || n->text.empty()) return def;
50	    try {
51	        return std::stod(n->text);
52	    } catch (...) { return def; }
53	}
54	[[nodiscard]] inline std::uint64_t lp_text_u(cx::XmlNode const* n, std::uint64_t def) noexcept {
55	    if (n == nullptr || n->text.empty()) return def;
56	    try {
57	        return static_cast<std::uint64_t>(std::stoull(n->text));
58	    } catch (...) { return def; }
59	}
60	[[nodiscard]] inline double lp_attr_d(cx::XmlNode const* n, std::string_view k, double def) noexcept {
61	    if (n == nullptr || !n->has_attr(k)) return def;
62	    try {
63	        return std::stod(n->attr(k));
64	    } catch (...) { return def; }
65	}
66	[[nodiscard]] inline KeyDistribution lp_keydist(std::string const& s) noexcept {
67	    if (s == "zipfian") return KeyDistribution::Zipfian;
68	    if (s == "latest") return KeyDistribution::Latest;
69	    return KeyDistribution::Uniform; // Default + Fallback für (noch) nicht unterstützte (real-corpus/lognormal)
