73	/// parse_load_profile — comdare_load_profile-XML → LoadProfile. nullopt bei fehlender/falscher Datei / falschem Wurzel-Tag.
74	[[nodiscard]] inline std::optional<LoadProfile> parse_load_profile(std::filesystem::path const& xml_file) {
75	    std::string const content = detail::lp_read_file(xml_file);
76	    auto              root    = cx::parse_document(content);
77	    if (!root.has_value() || root->tag != "comdare_load_profile") return std::nullopt;
78	
79	    LoadProfile lp;
80	    lp.id            = root->attr("id");
81	    lp.catalog_lp_id = root->attr("lp_id");
82	    lp.paper_ref     = root->attr("paper_ref");
83	    if (auto const* meta = root->child("metadata"))
84	        if (auto const* nm = meta->child("name")) lp.pretty_name = nm->text;
85	
86	    auto const* wl = root->child("workload");
87	    if (wl == nullptr || lp.id.empty()) return std::nullopt;
88	
89	    WorkloadConfig& c = lp.config;
90	    c.seed            = detail::lp_text_u(wl->child("seed"), 42);
91	    if (c.seed == 0) c.seed = 42;
92	    lp.records        = detail::lp_text_u(wl->child("records"), 0);
93	    lp.num_operations = detail::lp_text_u(wl->child("num_operations"), 0);
94	    // MAJOR-MESS-05 (Mess-Validität, Audit A1): <op_mix> ist die Workload-DEFINITION (Achse 2). Fehlt der Knoten,
95	    // würde der WorkloadConfig-Default (50/40/9/1 inkl. 1% Clear) STILL eingesetzt → ein anderes Profil gemessen als
96	    // dokumentiert. Darum HART ablehnen statt still defaulten: kein <op_mix> ⇒ kein gültiges Lastprofil (nullopt).
97	    auto const* om = wl->child("op_mix");
98	    if (om == nullptr) return std::nullopt;
99	    c.pct_insert = detail::lp_attr_d(om, "insert", 0.0);
100	    c.pct_lookup = detail::lp_attr_d(om, "lookup", 0.0);
101	    c.pct_erase  = detail::lp_attr_d(om, "erase", 0.0);
102	    c.pct_clear  = detail::lp_attr_d(om, "clear", 0.0);
103	    c.pct_scan   = detail::lp_attr_d(om, "scan", 0.0);
104	    c.pct_rmw    = detail::lp_attr_d(om, "rmw", 0.0);
105	    // …und ein LEERES op_mix (alle Anteile 0 / keine Op-Attribute) ist ebenso ungültig — sonst liefe ein Profil ohne
106	    // jede Operation (Summe 0 → WorkloadConfig::is_valid()==false ⇒ Generator normalisiert nicht). Ehrlich ablehnen.
107	    if ((c.pct_insert + c.pct_lookup + c.pct_erase + c.pct_clear + c.pct_scan + c.pct_rmw) <= 0.0) return std::nullopt;
108	    auto const* kd       = wl->child("key_distribution");
109	    c.key_distribution   = detail::lp_keydist(kd != nullptr ? kd->text : std::string{"uniform"});
110	    c.zipfian_theta      = detail::lp_text_d(wl->child("zipfian_theta"), 0.99);
111	    c.negative_query_pct = detail::lp_text_d(wl->child("negative_query_pct"), 0.0);
112	    c.scan_length_max    = detail::lp_text_u(wl->child("scan_length_max"), 100);
113	    // Skala: XML-Default für num_operations/key-range; der Aufrufer überschreibt mit der Harness-Skala.
114	    c.num_operations = (lp.num_operations > 0) ? static_cast<std::size_t>(lp.num_operations) : 1000;
115	    c.key_min        = 1;
116	    c.key_max        = (lp.records > 1) ? lp.records : 1'000'000ULL;
117	    return lp;
118	}
