120	/// discover_load_profiles — alle gültigen *.xml-Lastprofile in `dir` → [(id, pfad)], alphabetisch nach id.
121	/// Das ist die Werte-Menge der dynamischen Workload-Achse (Achse 2).
122	[[nodiscard]] inline std::vector<std::pair<std::string, std::filesystem::path>>
123	discover_load_profiles(std::filesystem::path const& dir) {
124	    std::vector<std::pair<std::string, std::filesystem::path>> out;
125	    std::error_code                                            ec;
126	    if (!std::filesystem::is_directory(dir, ec)) return out;
127	    for (auto const& entry : std::filesystem::directory_iterator(dir, ec)) {
128	        if (!entry.is_regular_file() || entry.path().extension() != ".xml") continue;
129	        if (auto lp = parse_load_profile(entry.path())) out.emplace_back(lp->id, entry.path());
130	    }
131	    std::sort(out.begin(), out.end(), [](auto const& a, auto const& b) { return a.first < b.first; });
132	    return out;
133	}
