25	// Sehr simpler XML-Tag-Extraktor: <tag id="..."><nested>...</nested></tag>
26	std::vector<PermutationEntry> parse_xml_string(std::string const& content, std::string const& tag_name) {
27	    std::vector<PermutationEntry> entries;
28	    std::regex                    open_tag{"<" + tag_name + "\\s+id\\s*=\\s*\"([^\"]+)\"\\s*>"};
29	    std::regex                    inner_tag{"<(\\w+)>([^<]+)</\\w+>"};
30	    auto                          it  = std::sregex_iterator(content.begin(), content.end(), open_tag);
31	    auto                          end = std::sregex_iterator();
32	    for (; it != end; ++it) {
33	        PermutationEntry entry;
34	        entry.id = (*it)[1].str();
35	        // Find closing tag
36	        auto        close_pos = content.find("</" + tag_name + ">", it->position() + it->length());
37	        std::string inner    = content.substr(it->position() + it->length(), close_pos - it->position() - it->length());
38	        auto        inner_it = std::sregex_iterator(inner.begin(), inner.end(), inner_tag);
39	        auto        inner_end = std::sregex_iterator();
40	        for (; inner_it != inner_end; ++inner_it) { entry.attributes[(*inner_it)[1].str()] = (*inner_it)[2].str(); }
41	        entries.push_back(std::move(entry));
42	    }
43	    return entries;
44	}
