46	// KF-1 (2026-06-02): Helfer fuer den Thesis-Profil-Parser.
47	[[nodiscard]] std::vector<std::string> split_ws(std::string const& s) {
48	    std::vector<std::string> out;
49	    std::size_t              i = 0;
50	    while (i < s.size()) {
51	        while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) ++i;
52	        std::size_t start = i;
53	        while (i < s.size() && !std::isspace(static_cast<unsigned char>(s[i]))) ++i;
54	        if (i > start) out.push_back(s.substr(start, i - start));
55	    }
56	    return out;
57	}
