59	[[nodiscard]] int to_int(std::string const& s, int def) {
60	    int         v     = def;
61	    auto const* begin = s.data();
62	    auto const* end   = s.data() + s.size();
63	    auto [ptr, ec]    = std::from_chars(begin, end, v);
64	    (void)ptr;
65	    return (ec == std::errc{}) ? v : def;
66	}
