112	AlgorithmProfile XmlConfigParser::parse_profile(std::filesystem::path const& profile_xml) const {
113	    AlgorithmProfile prof;
114	    if (!std::filesystem::exists(profile_xml)) return prof;
115	    std::string content = read_file(profile_xml);
116	
117	    // id="..." + paper_ref="..."  (eindeutiger Raw-String-Delimiter PAT — V12.7-Fix
118	    // gegen MSVC-Parser-Konflikt zwischen Pattern-`"` und Raw-String-Close)
119	    {
120	        std::regex  id_re{R"PAT(<comdare_algorithm_profile\s+id\s*=\s*"([^"]+)")PAT"};
121	        std::smatch m;
122	        if (std::regex_search(content, m, id_re)) prof.id = m[1].str();
123	    }
124	    {
125	        std::regex  pref_re{R"PAT(paper_ref\s*=\s*"([^"]+)")PAT"};
126	        std::smatch m;
127	        if (std::regex_search(content, m, pref_re)) prof.paper_ref = m[1].str();
128	    }
129	    {
130	        std::regex  type_re{R"PAT(pruefling_type\s*=\s*"([^"]+)")PAT"};
131	        std::smatch m;
132	        if (std::regex_search(content, m, type_re)) prof.pruefling_type = m[1].str();
133	    }
134	
135	    // Achsen aus <axes>...</axes>
136	    auto axes_open  = content.find("<axes>");
137	    auto axes_close = content.find("</axes>");
138	    if (axes_open != std::string::npos && axes_close != std::string::npos) {
139	        std::string axes_inner = content.substr(axes_open + 6, axes_close - axes_open - 6);
140	        std::regex  axis_re{R"(<(\w+)>([^<]+)</\w+>)"};
141	        auto        it  = std::sregex_iterator(axes_inner.begin(), axes_inner.end(), axis_re);
142	        auto        end = std::sregex_iterator();
143	        for (; it != end; ++it) { prof.axes[(*it)[1].str()] = (*it)[2].str(); }
144	    }
145	
146	    // key_value_signature
147	    {
148	        std::regex  kt{R"(<key_types>([^<]+)</key_types>)"};
149	        std::smatch m;
150	        if (std::regex_search(content, m, kt)) prof.key_types = m[1].str();
151	    }
152	    {
153	        std::regex  vt{R"(<value_types>([^<]+)</value_types>)"};
154	        std::smatch m;
155	        if (std::regex_search(content, m, vt)) prof.value_types = m[1].str();
156	    }
157	    // V19.1 — expected_workload (optional, ueberschreibt V11.2-Heuristik)
158	    {
159	        std::regex  ew{R"(<expected_workload>([^<]+)</expected_workload>)"};
160	        std::smatch m;
161	        if (std::regex_search(content, m, ew)) prof.expected_workload = m[1].str();
162	    }
163	    // V29.A — allocator_override (optional, ueberschreibt axes/allocator)
164	    {
165	        std::regex  ao{R"(<allocator_override>([^<]+)</allocator_override>)"};
166	        std::smatch m;
167	        if (std::regex_search(content, m, ao)) prof.allocator_override = m[1].str();
168	    }
169	    return prof;
170	}
