172	std::vector<Messreihe> XmlConfigParser::load_messreihen(std::filesystem::path const& messreihen_xml) const {
173	    std::vector<Messreihe> result;
174	    if (!std::filesystem::exists(messreihen_xml)) return result;
175	    std::string content = read_file(messreihen_xml);
176	
177	    std::regex           reihe_re{R"PAT(<messreihe\s+id\s*=\s*"([^"]+)"\s*>([\s\S]*?)</messreihe>)PAT"};
178	    std::sregex_iterator reihe_it{content.cbegin(), content.cend(), reihe_re};
179	    std::sregex_iterator reihe_end{};
180	    for (; reihe_it != reihe_end; ++reihe_it) {
181	        Messreihe r;
182	        r.id              = (*reihe_it)[1].str();
183	        std::string inner = (*reihe_it)[2].str();
184	
185	        std::regex  mode_re{R"(<mode>(\w+)</mode>)"};
186	        std::smatch mm;
187	        if (std::regex_search(inner, mm, mode_re)) r.mode = parse_mode(mm[1].str());
188	
189	        std::regex           prof_re{R"(<profile>([^<]+)</profile>)"};
190	        std::sregex_iterator prof_it{inner.cbegin(), inner.cend(), prof_re};
191	        std::sregex_iterator prof_end{};
192	        for (; prof_it != prof_end; ++prof_it) { r.sota_profile_refs.push_back((*prof_it)[1].str()); }
193	        result.push_back(std::move(r));
194	    }
195	    return result;
196	}
