198	// KF-1 (2026-06-02): comdare_thesis_profile-Parser ueber den self-contained XML-DOM.
199	std::optional<ThesisProfile> XmlConfigParser::parse_thesis_profile(std::filesystem::path const& xml_file) const {
200	    if (!std::filesystem::exists(xml_file)) return std::nullopt;
201	    std::string content = read_file(xml_file);
202	    auto        root    = comdare::common::xml::parse_document(content);
203	    if (!root || root->tag != "comdare_thesis_profile") return std::nullopt;
204	
205	    ThesisProfile tp;
206	    tp.id             = root->attr("id");
207	    tp.schema_version = to_int(root->attr("schema_version", "0"), 0);
208	
209	    if (auto const* bt = root->child("base_tiers")) {
210	        for (auto const* t : bt->children_named("tier"))
211	            tp.base_tiers.push_back({t->attr("id"), t->attr("profile_ref"), t->attr("paper_ref")});
212	    }
213	    if (auto const* pa = root->child("permute_axes")) {
214	        for (auto const* a : pa->children_named("axis")) {
215	            ThesisAxisSpec ax;
216	            ax.ref = a->attr("ref");
217	            for (auto const* v : a->children_named("value")) ax.values.push_back(v->text);
218	            if (ax.ref == "cacheline") { // per-Organ Cache-Line-Unterachse (KF-3)
219	                ax.per_organ = split_ws(a->attr("per_organ"));
220	                for (auto const* x : a->children_named("line_size")) ax.line_sizes.push_back(x->text);
221	                for (auto const* x : a->children_named("alignment")) ax.alignments.push_back(x->text);
222	                for (auto const* x : a->children_named("sw_prefetch_hint")) ax.sw_prefetch_hints.push_back(x->text);
223	            }
224	            tp.permute_axes.push_back(std::move(ax));
225	        }
226	    }
227	    if (auto const* cd = root->child("compile_dims")) {
228	        if (auto const* w = cd->child("workloads")) tp.workloads = w->text_tokens();
229	        if (auto const* t = cd->child("telemetry")) {
230	            tp.telemetry_mode   = t->attr("mode");
231	            tp.telemetry_silent = (t->attr("silent") == "true");
232	        }
233	    }
234	    if (auto const* rd = root->child("runtime_dynamic")) {
235	        if (auto const* tc = rd->child("thread_count")) tp.thread_counts = tc->text_tokens();
236	        if (auto const* hp = rd->child("hw_prefetcher")) tp.hw_prefetcher = hp->text_tokens();
237	    }
238	    if (auto const* fc = root->child("fixed_conditions")) tp.fixed_conditions = fc->attrs;
239	    if (auto const* rep = root->child("repetitions")) {
240	        tp.repetitions             = to_int(rep->attr("count", "3"), 3);
241	        tp.repetitions_interpolate = (rep->attr("interpolate", "false") == "true");
242	        tp.repetitions_overlay     = (rep->attr("overlay_in_chart", "true") == "true");
243	    }
244	    if (auto const* ms = root->child("modes")) {
245	        for (auto const* m : ms->children_named("mode")) {
246	            ThesisMode md;
247	            md.name          = m->attr("name");
248	            md.merge         = m->attr("merge");
249	            md.active_axes   = split_ws(m->attr("active_axes"));
250	            md.pruefling     = m->attr("pruefling");
251	            md.replaces_axes = split_ws(m->attr("replaces_axes"));
252	            tp.modes.push_back(std::move(md));
253	        }
254	    }
255	    if (auto const* sa = root->child("static_axes")) tp.static_axes_from = sa->attr("from");
256	    if (auto const* kv = root->child("key_value_signature")) {
257	        if (auto const* k = kv->child("key_types")) tp.key_types = k->text;
258	        if (auto const* v = kv->child("value_types")) tp.value_types = v->text;
259	    }
260	
261	    // ── S1 (Increment 2, 2026-06-18): die 4 deklarativen m3v2-Selektions-Konstrukte. ADDITIV — fehlen sie,
262	    //    bleiben die Felder leer/Default (kein Einfluss auf base_pilot/cacheline_study oder den Round-Trip). ──
263	    // (a) <working_set_sweep>{N-Liste}</working_set_sweep> — whitespace-getrennte Record-Zahlen (wie thread_count).
264	    if (auto const* ws = root->child("working_set_sweep")) tp.working_set_sweep = ws->text_tokens();
265	    // (b) <axis_sweeps>/<axis_sweep axis=".." baseline="index0"/> — je eine Achse gegen die feste Baseline.
266	    if (auto const* sw = root->child("axis_sweeps")) {
267	        for (auto const* a : sw->children_named("axis_sweep")) {
268	            ThesisAxisSweep as;
269	            as.axis     = a->attr("axis");
270	            as.baseline = a->attr("baseline", "index0");
271	            tp.axis_sweeps.push_back(std::move(as));
272	        }
273	    }
274	    // (c) <sota_series_set>/<sota_series id=".." lebewesen=".." merge=".."/> — die SOTA-/PRT-ART-Reihen A/B/C.
275	    if (auto const* ss = root->child("sota_series_set")) {
276	        for (auto const* s : ss->children_named("sota_series")) {
277	            ThesisSotaSeries sr;
278	            sr.id             = s->attr("id");
279	            sr.lebewesen      = s->attr("lebewesen");
280	            sr.merge          = s->attr("merge");
281	            sr.pruefling_type = s->attr("pruefling_type"); // #171: optional; leer ⇒ aus merge abgeleitet
282	            tp.sota_series.push_back(std::move(sr));
283	        }
284	    }
285	    // (d) <run_options cap=".." platform=".." build_version=".." resume=".."/> — Lauf-Steuerungs-Defaults.
286	    if (auto const* ro = root->child("run_options")) {
287	        tp.run_options.cap           = to_int(ro->attr("cap", "0"), 0);
288	        tp.run_options.platform      = ro->attr("platform");
289	        tp.run_options.build_version = ro->attr("build_version");
290	        if (ro->has_attr("resume")) {
291	            tp.run_options.resume     = (ro->attr("resume") == "true" || ro->attr("resume") == "1");
292	            tp.run_options.resume_set = true;
293	        }
294	    }
295	    return tp;
296	}
