19	namespace comdare::common::xml {
20	
21	struct XmlNode {
22	    std::string                        tag;
23	    std::map<std::string, std::string> attrs;
24	    std::vector<XmlNode>               children;
25	    std::string                        text; // direkter Textinhalt (getrimmt)
26	
27	    [[nodiscard]] XmlNode const* child(std::string_view name) const {
28	        for (auto const& c : children)
29	            if (c.tag == name) return &c;
30	        return nullptr;
31	    }
32	    [[nodiscard]] std::vector<XmlNode const*> children_named(std::string_view name) const {
33	        std::vector<XmlNode const*> out;
34	        for (auto const& c : children)
35	            if (c.tag == name) out.push_back(&c);
36	        return out;
37	    }
38	    [[nodiscard]] std::string attr(std::string_view key, std::string_view def = "") const {
39	        auto it = attrs.find(std::string{key});
40	        return (it == attrs.end()) ? std::string{def} : it->second;
41	    }
42	    [[nodiscard]] bool has_attr(std::string_view key) const { return attrs.find(std::string{key}) != attrs.end(); }
43	    // Whitespace-getrennte Tokens des Textinhalts (z.B. "A B C D E F" / "1 2 4").
44	    [[nodiscard]] std::vector<std::string> text_tokens() const {
45	        std::vector<std::string> out;
46	        std::size_t              i = 0;
47	        while (i < text.size()) {
48	            while (i < text.size() && std::isspace(static_cast<unsigned char>(text[i]))) ++i;
49	            std::size_t start = i;
50	            while (i < text.size() && !std::isspace(static_cast<unsigned char>(text[i]))) ++i;
51	            if (i > start) out.push_back(text.substr(start, i - start));
52	        }
53	        return out;
54	    }
55	};
56	
57	namespace detail {
58	
59	inline constexpr auto npos = std::string_view::npos;
60	
61	inline void decode_entities(std::string& s) {
62	    struct E {
63	        std::string_view from;
64	        char             to{};
65	    };
66	    static constexpr E kEnt[] = {{"&lt;", '<'}, {"&gt;", '>'}, {"&quot;", '"'}, {"&apos;", '\''}, {"&amp;", '&'}};
67	    for (auto const& e : kEnt) {
68	        std::size_t pos = 0;
69	        while ((pos = s.find(e.from, pos)) != std::string::npos) {
70	            s.replace(pos, e.from.size(), 1, e.to);
71	            pos += 1;
72	        }
73	    }
74	}
75	
76	inline std::string trimmed(std::string_view s) {
77	    std::size_t a = 0, b = s.size();
78	    while (a < b && std::isspace(static_cast<unsigned char>(s[a]))) ++a;
79	    while (b > a && std::isspace(static_cast<unsigned char>(s[b - 1]))) --b;
80	    return std::string{s.substr(a, b - a)};
81	}
82	
83	struct Cursor {
84	    std::string_view s;
85	    std::size_t      i = 0;
86	};
87	
88	inline bool starts_with(Cursor const& c, std::string_view p) { return c.s.substr(c.i, p.size()) == p; }
89	inline void skip_ws(Cursor& c) {
90	    while (c.i < c.s.size() && std::isspace(static_cast<unsigned char>(c.s[c.i]))) ++c.i;
91	}
92	// Kommentare / XML-Deklaration / DOCTYPE ueberspringen.
93	inline void skip_misc(Cursor& c) {
94	    for (;;) {
95	        skip_ws(c);
96	        if (starts_with(c, "<!--")) {
97	            auto e = c.s.find("-->", c.i);
98	            c.i    = (e == npos) ? c.s.size() : e + 3;
99	        } else if (starts_with(c, "<?")) {
100	            auto e = c.s.find("?>", c.i);
101	            c.i    = (e == npos) ? c.s.size() : e + 2;
102	        } else if (starts_with(c, "<!")) {
103	            auto e = c.s.find('>', c.i);
104	            c.i    = (e == npos) ? c.s.size() : e + 1;
105	        } else
106	            break;
107	    }
108	}
109	inline std::string read_name(Cursor& c) {
110	    std::size_t start = c.i;
111	    while (c.i < c.s.size()) {
112	        char ch = c.s[c.i];
113	        if (std::isalnum(static_cast<unsigned char>(ch)) || ch == '_' || ch == '-' || ch == ':' || ch == '.')
114	            ++c.i;
115	        else
116	            break;
117	    }
118	    return std::string{c.s.substr(start, c.i - start)};
119	}
120	
121	// Parst EIN Element ab '<'. Gibt false bei Wohlgeformtheits-Fehler.
122	inline bool parse_element(Cursor& c, XmlNode& out) {
123	    skip_misc(c);
124	    if (c.i >= c.s.size() || c.s[c.i] != '<') return false;
125	    ++c.i; // '<'
126	    out.tag = read_name(c);
127	    if (out.tag.empty()) return false;
128	
129	    // Attribute lesen bis '>' oder '/>'.
130	    for (;;) {
131	        skip_ws(c);
132	        if (c.i >= c.s.size()) return false;
133	        char ch = c.s[c.i];
134	        if (ch == '/') {
135	            if (starts_with(c, "/>")) {
136	                c.i += 2;
137	                return true;
138	            }
139	            return false;
140	        }
141	        if (ch == '>') {
142	            ++c.i;
143	            break;
144	        }
145	        std::string an = read_name(c);
146	        if (an.empty()) return false;
147	        skip_ws(c);
148	        if (c.i >= c.s.size() || c.s[c.i] != '=') return false;
149	        ++c.i; // '='
150	        skip_ws(c);
151	        if (c.i >= c.s.size()) return false;
152	        char q = c.s[c.i];
153	        if (q != '"' && q != '\'') return false;
154	        ++c.i;
155	        std::size_t vstart = c.i;
156	        while (c.i < c.s.size() && c.s[c.i] != q) ++c.i;
157	        std::string av{c.s.substr(vstart, c.i - vstart)};
158	        if (c.i < c.s.size()) ++c.i; // schliessendes Quote
159	        decode_entities(av);
160	        out.attrs[an] = std::move(av);
161	    }
162	
163	    // Inhalt: Text + Kind-Elemente bis </tag>.
164	    std::string text;
165	    for (;;) {
166	        std::size_t tstart = c.i;
167	        while (c.i < c.s.size() && c.s[c.i] != '<') ++c.i;
168	        text.append(c.s.substr(tstart, c.i - tstart));
169	        if (c.i >= c.s.size()) break;
170	        if (starts_with(c, "<!--")) {
171	            auto e = c.s.find("-->", c.i);
172	            c.i    = (e == npos) ? c.s.size() : e + 3;
173	            continue;
174	        }
175	        if (starts_with(c, "</")) {
176	            c.i += 2;
177	            read_name(c); // close-Name (tolerant; Wohlgeformtheit vorausgesetzt)
178	            skip_ws(c);
179	            if (c.i < c.s.size() && c.s[c.i] == '>') ++c.i;
180	            break;
181	        }
182	        XmlNode child;
183	        if (!parse_element(c, child)) return false;
184	        out.children.push_back(std::move(child));
185	    }
186	    decode_entities(text);
187	    out.text = trimmed(text);
188	    return true;
189	}
