194	[[nodiscard]] inline std::optional<XmlNode> parse_document(std::string_view xml) {
195	    detail::Cursor c{xml, 0};
196	    detail::skip_misc(c);
197	    XmlNode root;
198	    if (!detail::parse_element(c, root)) return std::nullopt;
199	    return root;
200	}
