83	    std::size_t   sota_rows        = 0; // CSV-Zeilen aus den SOTA-Reihen-Paessen (frisch+resumiert)
84	    std::size_t   basis_binary_ids = 0; // distinkte Basis-binary_ids, die in DIESEM Lauf selektiert wurden
85	    std::size_t   sota_binary_ids  = 0; // distinkte SOTA-Reihen-binary_ids, die gebaut/gemessen wurden
86	    std::uint64_t any_measured     = 0;
87	    std::uint64_t any_resumed      = 0;
88	};
