98	/// run_profile — DIE EINE deklarative CEB-Eintritts-API (S7c). Faehrt aus EINEM Profil BEIDE Subsets:
99	///   (1) den BASIS-Pass (permute_axes → source_catalog) und
100	///   (2) je <sota_series> einen SOTA-Reihen-Pass (sota_catalog), getaggt A/B/C,
101	/// ueber EINE vereinigte SourceGenFn (make_union_source_gen) in EINE CSV. Die per-Pass-Iteration ueber
102	/// <working_set_sweep> bleibt erhalten (aeussere N-Schleife). Resume/binary_id-Stabilitaet wie der heutige
103	/// Treiber (run_lazy_static_then_dynamic je Pass; #139-Stamp pro Pass).
104	[[nodiscard]] inline RunProfileResult run_profile(RunProfileArgs const& a) {
105	    RunProfileResult res;
106	
107	    // ── (0) Profil EINMAL parsen (die EINZIGE WHAT-Quelle). ──
108	    std::optional<cx::ThesisProfile> const tp_opt = load_thesis_profile(a.profile_path);
109	    if (!tp_opt) {
110	        std::cerr << "run_profile: Profil '" << a.profile_path.string()
111	                  << "' nicht lesbar (parse_thesis_profile=nullopt) — Abbruch.\n";
112	        res.exit_code = 5;
113	        return res;
114	    }
115	    auto const&             tp        = *tp_opt;
116	    std::string const       mode_name = tp.modes.empty() ? std::string{"m3v2_base"} : tp.modes.front().name;
117	    ProfileRunOptions const ro        = profile_run_options(tp);
118	
119	    // ── (1) Der BASIS-Baum (build_profile_basis_levels = build_axis_levels OHNE tier-Ebene). ──
120	    auto                       factory = std::make_shared<ex::ExperimentNodeFactory>();
121	    ex::ExperimentTree         basis_tree{factory};
122	    std::vector<ex::AxisLevel> basis_levels = build_profile_basis_levels(tp, mode_name, /*with_dynamic=*/true);
123	    // ── (1b) ACHSE 2 (Lastprofil) als DYNAMISCHE Ebene injizieren (STRANG-A-Wiring-Luecke, 2026-06-19).
124	    //    build_axis_levels emittiert die runtime_dynamic-DynDims (concurrency.thread_count / prefetch.hw_prefetcher /
125	    //    repetition.repetition_index), aber NICHT die Lastprofil-Achse (die wird separat ueber discover_load_profiles
126	    //    entdeckt → a.workload_values). Ohne diese Ebene fehlt im setting_label das Segment "workload.workload_id=X";
127	    //    der Iterator faellt dann auf run_observable_perm (fixer Workload, KEIN Zwei-Phasen-Cache-Warmup) zurueck →
128	    //    JEDE Zeile two_phase_valid=0 (Mess-UNGUELTIG). Mit der Ebene laeuft run_workload_perm mit Pflicht-Rollback
129	    //    → two_phase_valid=1. Gleiche Konvention wie die uebrigen DynDims (block_id.variable=value): block_id
130	    //    "workload", variable "workload_id" (lazy_extract_workload_id sucht genau "workload_id="). is_static=false ⇒
131	    //    veraendert die binary_id NICHT (Round-Trip-Gate unberuehrt).
132	    if (!a.workload_values.empty())
133	        basis_levels.push_back(
134	            ex::AxisLevel{"workload", a.workload_values, /*is_static=*/false, "workload_id", "workload"});
135	    basis_tree.build(basis_levels);
136	    ex::StaticBinaryView const basis_view = basis_tree.static_binary_view();
137	
138	    // ── (2) cap/resume/Tags (Profil-Defaults; Override aus den Args). ──
139	    std::size_t eff_cap = a.max_binaries;

204	/// run_workload_perm — treibt EIN Lastprofil (workload_id) über `workload_driver::run_workload_profile` statt
205	/// des hartgecodeten insert/lookup-Loops (run_observable_perm). Die Op-Sequenz wird host-seitig reproduzierbar
206	/// materialisiert (gleiche Config+Seed ⇒ bit-identische Sequenz über alle Binaries). Jede gemessene Op läuft
207	/// über den Zwei-Phasen-Cache-Warmup (save→warmup→rollback→measure), der für die Mess-GÜLTIGKEIT PFLICHT ist
208	/// ([[feedback_two_phase_warmup_mandatory_validity]]): Ohne exakten Rollback ist die Messung UNGÜLTIG — wir
209	/// markieren das (two_phase_valid=false) und erzeugen KEINE stille Kalt-Messung als gültiges Ergebnis.
210	/// Unbekanntes Profil → Rückwärts-Kompat-Fallback auf den alten fixen Workload (run_observable_perm).
211	[[nodiscard]] inline PermResult run_workload_perm(anatomy::IObservableTier& tier, anatomy::IRollbackableTier* rollback,
212	                                                  anatomy::IScannableTier* scan, std::string const& binary_id,
213	                                                  std::string_view workload_id, std::uint64_t n_ops, std::uint64_t seed,
214	                                                  std::uint64_t                                    load_records = 0,
215	                                                  std::map<std::string, wd::WorkloadConfig> const* registry = nullptr,
216	                                                  builder::IPmcSource*                             pmc      = nullptr) {
217	    // Achse 2 (#135): workload_id zuerst aus der XML-Lastprofil-Registry (Charakteristik aus dem XML); sonst aus
218	    // dem hartcodierten profile_by_name (env-String-Rückwärts-Kompat). Skala (records/n_ops) setzt der Aufrufer.
219	    wd::WorkloadConfig cfg{};
220	    bool               resolved = false;
221	    if (registry != nullptr) {
222	        auto const it = registry->find(std::string(workload_id));
223	        if (it != registry->end()) {
224	            cfg      = it->second;
225	            resolved = true;
226	        }
227	    }
228	    if (!resolved) {
229	        cfg = wd::profile_by_name(workload_id, seed, static_cast<std::size_t>(n_ops));
230	        if (cfg.name.empty())
231	            return run_observable_perm(tier, binary_id, n_ops, pmc); // unbekannt → alter fixer Workload
232	    }
233	    cfg.num_operations = static_cast<std::size_t>(n_ops);
234	    // YCSB Load-/Run-Phasen-Trennung (INC-3c): `records` Sätze werden VOR der gemessenen Run-Phase befüllt (load),
235	    // und die Key-Verteilung wird auf [1, records] ausgerichtet → Lookups/Scans treffen befüllte Keys. Ohne diese
236	    // Load-Phase wären read-heavy/scan-Profile (C/E) auf leerem Tier 100% Miss = ungültig. Default records = n_ops.
237	    std::uint64_t const records = (load_records > 0) ? load_records : n_ops;
238	    cfg.key_min                 = 1;
239	    cfg.key_max                 = (records > 1) ? records : 2; // key_max>key_min Pflicht (WorkloadConfig::is_valid)
240	
241	    PermResult r;
242	    r.profile_name = std::string(workload_id); // schon hier (Gate-Früh-Return + CSV nutzen den Achsen-Wert)
243	    // (Audit K9 / V5-I4) import → GATE → (nur bei pass) messen: nicht-std::map-konforme Hülle erzeugt KEINE gültige
244	    // Performance-Zeile (gated≠gültig). Das Gate läuft VOR Load-/Run-Phase (es leert das Tier selbst).
245	    apply_conformance_gate_(tier, r);
246	    if (!r.conformance_passed) return gate_failed_result_(std::move(r), binary_id);
247	
248	    // GÜLTIGKEIT: Zwei-Phasen-Warmup Pflicht. Rollback-Exaktheit (Adapter-strukturell) auf leerem Tier prüfen (billig).
249	    tier.tier_clear();
250	    bool const rb_exact = (rollback != nullptr) && acd::rollback_is_empirically_exact(tier, rollback);
251	    r.two_phase_valid   = rb_exact;
252	
253	    // MINOR-MESS-02 (Mess-Validität, Audit A1): LOAD + Run liegen NACH der bestandenen rb_exact-Probe. Wirft eine
254	    // Kapsel-Op hier (z.B. std::bad_alloc/OOM beim Befüllen großer `records` oder beim CoW-Memento), so wäre der bis
255	    // dahin gesetzte r.two_phase_valid=rb_exact eine GEFÄLSCHTE Gültigkeit über einer abgebrochenen Mess-Last
256	    // (Teil-/Nullzähler). Darum: die ganze Mess-Region kapseln und bei JEDER Ausnahme die Messung ehrlich als
257	    // UNGÜLTIG markieren (two_phase_valid=false, genullte Matrix-Zeile) statt sie als valide einzuspielen.
258	    // (Hinweis: ein vom Tier INTERN via catch(...) verschluckter OOM bleibt eine ehrliche Restlimitierung — s.
259	    //  le_limitierung-Zeile „Kapsel-internes OOM"; diese Schranke deckt den nach außen propagierten Fall ab.)
260	    try {
261	        // LOAD-Phase (UNGEMESSEN): records Sätze einfügen → befülltes Tier für die gemessene Run-Phase (YCSB-Load).
262	        tier.tier_clear();
263	        for (std::uint64_t i = 1; i <= records; ++i) (void)tier.tier_insert(i, i * 7u + 1u);
264	        // #216-H2: Observer-Statistik nach Load nullen (daten-erhaltend) -> axis_stats misst nur die Run-Phase; Wall-Clock/PMC klammern weiterhin nur die Run-Phase.
265	        tier.tier_reset_statistics();
266	
267	        wd::WorkloadGenerator             gen{cfg}; // gleiche Config+Seed ⇒ bit-identische Op-Sequenz je Binary
268	        std::vector<wd::WorkloadOp> const ops = gen.generate_all();
269	        // #156-De-Risk: PMC klammert NUR die gemessene Run-Phase (run_workload_profile) — die LOAD-Phase oben ist
270	        // ungemessen, also bewusst AUSSERHALB des begin()/end()-Intervalls. EINMAL pro Treiber-Lauf erzeugte Quelle.
271	        if (pmc != nullptr) pmc->begin();
272	        wd::WorkloadRunResult const res =
273	            wd::run_workload_profile(tier, rb_exact ? rollback : nullptr, ops, cfg.name, scan);
274	        if (pmc != nullptr) r.pmc = pmc->end();
275	
276	        // total_ns + GOAL-M1.1/L1: per-Op-Art-Aggregate (n/p50/p99, Reihenfolge kOpKindNames) + timed_ops als
277	        // Σ der Samples — die korrekte ns_per_op-Basis (Audit K2: der fixe 2*n_ops-Divisor galt nur dem Legacy-Pfad).
278	        std::int64_t                                          total = 0;
